// Load styles in the shadowRoot so we don't leak it.
const style = document.createElement("link");
style.rel = "stylesheet";
style.href = "chrome://messenger/skin/calendar/calendarDialogRow.css";

const template = document.getElementById("calendarDialogRowTemplate");
const clonedNode = template.content.cloneNode(true);
shadowRoot.append(clonedNode, style);

.row {
  flex-grow: 1;
  padding-inline: var(--calendar-dialog-row-padding-inline);
  display: grid;
  grid-template-columns: auto 1fr;
  grid-template-rows: auto 1fr;
  align-items: center;
  gap: var(--calendar-dialog-row-content-gap) var(--calendar-dialog-row-column-gap);

  :host([expanding]) & {
    padding-inline-end: 0;
  }

  :host([expanded]) & {
    padding-block: var(--calendar-dialog-expanded-row-padding-block);
    row-gap: var(--calendar-dialog-expanded-row-content-gap);
  }
